-- Columns dropped by 05c. Recreate, then restore values (only rows that differ from the default are listed).
ALTER TABLE public.user_profiles ADD COLUMN IF NOT EXISTS workout_join_popups_enabled boolean DEFAULT true;
ALTER TABLE public.workouts ADD COLUMN IF NOT EXISTS creator_popup_shown boolean DEFAULT false;
ALTER TABLE public.workouts ADD COLUMN IF NOT EXISTS ready_expires_at timestamp with time zone;
GRANT INSERT (workout_join_popups_enabled), UPDATE (workout_join_popups_enabled) ON public.user_profiles TO authenticated;
UPDATE public.workouts w SET ready_expires_at = (x->>'v')::timestamptz FROM jsonb_array_elements($j$[{"v": "2026-10-02T20:16:19.656116+00:00", "id": "53173101-2ea9-41c9-a199-fa20437c9274"}, {"v": "2026-07-03T14:44:37.460404+00:00", "id": "423eafdc-693c-4ebf-be2d-2a295edbb3cb"}, {"v": "2026-07-03T18:58:03.154402+00:00", "id": "6dc41277-743c-46e3-9ed0-dddc81affa10"}, {"v": "2026-07-03T19:25:52.759636+00:00", "id": "a795b20d-2617-4b10-82d0-c4d7f9c35821"}, {"v": "2026-06-10T23:31:32.468246+00:00", "id": "5aa11874-18bf-4b1f-96ef-d2e0ca435d4d"}, {"v": "2026-07-02T18:07:11.992996+00:00", "id": "5a6f2512-7e4c-43fc-baa8-f77e38f0fc4a"}]$j$::jsonb) x WHERE w.id = (x->>'id')::uuid;
